'use strict';
const $=id=>document.getElementById(id), form=$('form'), fields=form.elements;
const icons={plus:'M12 5v14M5 12h14',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 14h12v7H6z M17 11h1',box:'M3 7l9-4 9 4v11l-9 4-9-4z M3 7l9 4 9-4 M12 11v11 M7 5l9 4',layers:'M2 7l10-5 10 5-10 5z M2 12l10 5 10-5 M2 17l10 5 10-5',flag:'M5 22V3 Q9 1 13 4 Q16 6 21 3l-2 9 Q15 15 11 12 Q8 10 5 12'};
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML='<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"><path d="'+icons[el.dataset.icon]+'"/></svg>');
const esc=v=>String(v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
let db,state,undoId,channel,timer;
function notify(msg){clearTimeout(timer);$('notice').textContent=msg;timer=setTimeout(()=>$('notice').textContent='',4500)}
function makeState(){const lots=[['Snow Pea','P26-01',17],['Calendula','C26-02',9],['Bush Bean','B25-04',4]].map(([name,code,qty],i)=>({name,code,qty,id:i+1}));
return {lots,events:lots.map(l=>({id:l.id,lot:l.id,type:'Opening balance',delta:l.qty,balance:l.qty,time:Date.now()}))}}
// Every writer reads the latest ledger within the same serialized write transaction.
function access(change){return new Promise((resolve,reject)=>{const tx=db.transaction('ledger',change?'readwrite':'readonly'),store=tx.objectStore('ledger'),get=store.get(1);let result,problem;
get.onsuccess=()=>{try{result=get.result||makeState();if(change){change(result);store.put(result,1)}}catch(e){problem=e;tx.abort()}};
tx.onabort=()=>reject(problem||tx.error||Error('Could not save inventory.'));tx.oncomplete=()=>{state=result;render();resolve()}})}
async function reload(){if(db)try{await access()}catch{notify('Inventory could not be read. Reopen the desk to retry.')}}
function boot(){const req=indexedDB.open('seed-ledger-desk',1);req.onupgradeneeded=()=>req.result.createObjectStore('ledger');req.onerror=()=>notify('Local storage is unavailable. Open this file in a browser with storage enabled.');
req.onsuccess=async()=>{db=req.result;await access(()=>{});if('BroadcastChannel' in window){channel=new BroadcastChannel('seed-ledger-updates');channel.onmessage=reload}}}
function options(lots){return lots.map(l=>'<option value="'+l.id+'">'+esc(l.name)+' · '+esc(l.code)+'</option>').join('')}
function render(){
const {lots,events}=state,q=$('search').value.trim().toLowerCase(),filter=$('filter').value;
$('packets').textContent=lots.reduce((n,l)=>n+l.qty,0);$('lots').textContent=lots.length;$('low').textContent=lots.filter(l=>l.qty<=3).length;
let shown=lots.filter(l=>(l.name+' '+l.code).toLowerCase().includes(q)&&(filter==='all'||(filter==='low')===(l.qty<=3)));
$('cards').innerHTML=shown.map(l=>'<article class="card"><div class="illustration"><canvas aria-hidden="true"></canvas><span class="meta">LOT '+esc(l.code)+'</span></div><div class="cardbody"><div class="titleline"><h3>'+esc(l.name)+'</h3><span class="badge '+(l.qty<=3?'warn':'')+'">'+(l.qty<=3?'Low stock':'In stock')+'</span></div><div class="balance" style="margin-top:14px"><span><strong>'+l.qty+'</strong> <small>packets</small></span><button class="link" data-lot="'+l.id+'">View activity ↗</button></div></div></article>').join('')||'<p class="empty">No lots match this search or stock filter.</p>';
$('cards').querySelectorAll('canvas').forEach((c,i)=>drawStudy(c,shown[i].name));
let chosen=$('lotfilter').value;$('lotfilter').innerHTML='<option value="">All lots</option>'+options(lots);$('lotfilter').value=chosen;
const reversed=new Set(events.filter(e=>e.original).map(e=>e.original));
$('rows').innerHTML=events.slice().reverse().filter(e=>!chosen||e.lot==chosen).map(e=>{const l=lots.find(l=>l.id===e.lot),status=reversed.has(e.id)?'Undone':e.original?'Reverses #'+e.original:'';
return '<tr><td><div class="entry"><span aria-hidden="true">'+(e.original?'↶':e.delta<0?'−':'+')+'</span><div>'+esc(e.type)+'<small>'+'#'+e.id+(e.reason?' · '+esc(e.reason):'')+'</small></div></div></td><td>'+esc(l.name)+'<small class="code" style="margin:0">'+esc(l.code)+'</small></td><td class="num '+(e.delta>0?'pos':'')+'">'+signed(e.delta)+'</td><td>'+e.balance+'</td><td class="date">'+esc(new Date(e.time).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}))+'<br>'+esc(new Date(e.time).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}))+'</td><td>'+(status?esc(status):e.type!=='Opening balance'?'<button class="link" data-undo="'+e.id+'">Undo</button>':'')+'</td></tr>'}).join('');
$('shelf').innerHTML='<h1>Seed library shelf list</h1><p>'+esc(new Date().toLocaleDateString())+' · '+lots.length+' lots · '+$('packets').textContent+' packets</p><table><thead><tr><th>Variety</th><th>Lot</th><th>Packets</th><th>Stock</th></tr></thead><tbody>'+lots.slice().sort((a,b)=>a.name.localeCompare(b.name)||a.code.localeCompare(b.code)).map(l=>'<tr><td>'+esc(l.name)+'</td><td>'+esc(l.code)+'</td><td>'+l.qty+'</td><td>'+(l.qty<=3?'Low stock':'In stock')+'</td></tr>').join('')+'</tbody></table>';
}
function signed(n){return n>0?'+'+n:String(n)}
function details(reset=false){const type=fields.type.value,donation=type==='Donation',correction=type==='Count correction';if(reset){let prev=fields.lot.value;fields.lot.innerHTML=options(state.lots)+(donation?'<option value="new">Create a lot…</option>':'');fields.lot.value=Array.from(fields.lot.options).some(o=>o.value===prev)?prev:String(state.lots[0].id)}
const fresh=fields.lot.value==='new',l=state.lots.find(l=>l.id==fields.lot.value);$('fresh').hidden=!fresh;fields.variety.required=fields.code.required=fresh;$('why').hidden=!correction;fields.reason.required=correction;fields.qty.min=correction?0:1;$('qlabel').textContent=correction?'Counted packets':donation?'Packets donated':'Packets to check out';$('hint').textContent=l?l.qty+' packets currently available.':'';form.querySelector('.error').textContent=''}
$('new').onclick=()=>{if(!state)return;form.reset();details(true);$('dialog').showModal()};fields.type.onchange=()=>details(true);fields.lot.onchange=()=>details();
function addEvent(s,l,type,delta,extra={}){const balance=l.qty+delta;if(!Number.isSafeInteger(balance)||balance<0)throw Error('There are too few packets for this change, or the quantity is too large.');l.qty=balance;s.events.push({id:s.events.length+1,lot:l.id,type,delta,balance,time:Date.now(),...extra})}
async function commit(dialog,change,message){const button=dialog.querySelector('button.primary');button.disabled=true;try{await access(change);dialog.close();channel?.postMessage(1);notify(message)}catch(e){dialog.querySelector('.error').textContent=e.message}finally{button.disabled=false}}
form.onsubmit=e=>{e.preventDefault();const type=fields.type.value,n=fields.qty.valueAsNumber,key=fields.lot.value,reason=fields.reason.value.trim();commit($('dialog'),s=>{if(!Number.isSafeInteger(n)||n<(type==='Count correction'?0:1))throw Error('Enter a valid whole packet quantity.');let l=s.lots.find(l=>l.id==key);
if(type==='Donation'&&key==='new'){const name=fields.variety.value.trim(),code=fields.code.value.trim().toUpperCase();if(!name||!code)throw Error('Enter the variety and lot code.');l=s.lots.find(l=>l.code.toUpperCase()===code&&l.name.toLowerCase()===name.toLowerCase());if(!l){l={id:s.lots.length+1,name,code,qty:0};s.lots.push(l)}}
if(type==='Count correction'&&!reason)throw Error('Enter a short reason for the correction.');if(type==='Checkout'&&n>l.qty)throw Error('Only '+l.qty+' packets are available.');addEvent(s,l,type,type==='Checkout'?-n:type==='Count correction'?n-l.qty:n,type==='Count correction'?{reason}:{})},'Entry saved.')};
$('cards').onclick=e=>{const btn=e.target.closest('[data-lot]');if(btn){$('lotfilter').value=btn.dataset.lot;render();location.hash='activity';$('activity').scrollIntoView()}};
$('rows').onclick=e=>{const btn=e.target.closest('[data-undo]');if(!btn)return;undoId=Number(btn.dataset.undo);const ev=state.events.find(e=>e.id===undoId),l=state.lots.find(l=>l.id===ev.lot);$('undotext').textContent='Reverse the '+ev.type.toLowerCase()+' for '+l.name+' ('+l.code+') and adjust stock by '+signed(-ev.delta)+' packets?';$('undo').querySelector('.error').textContent='';$('undo').showModal()};
$('undoform').onsubmit=e=>{e.preventDefault();commit($('undo'),s=>{const ev=s.events.find(e=>e.id===undoId);if(!ev||ev.original||ev.type==='Opening balance'||s.events.some(e=>e.original===undoId))throw Error('This entry cannot be undone.');addEvent(s,s.lots.find(l=>l.id===ev.lot),'Undo '+ev.type.toLowerCase(),-ev.delta,{original:undoId})},'Entry undone. Reversal recorded.')};
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('print').onclick=()=>state&&window.print();$('search').oninput=$('filter').onchange=$('lotfilter').onchange=()=>state&&render();window.onfocus=reload;window.onhashchange=()=>document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('current',a.hash===(location.hash||'#catalog')));window.onhashchange();boot();

// Small botanical studies drawn in local coordinates so the sheets scale for any display.
function drawStudy(canvas, variety) {
  const kind = /calendula/i.test(variety) ? 'flower' : /pea/i.test(variety) ? 'pea' : /bean/i.test(variety) ? 'bean' : 'leaf';
  const colors = {flower:['#eed4af','#744a32','#df9251'],pea:['#dae0b7','#4b6139','#a6b87c'],bean:['#d5dfd4','#3c5950','#8ea998'],leaf:['#dedec5','#526449','#a6b395']}[kind];
  const w=canvas.clientWidth||340,h=canvas.clientHeight||140,d=Math.min(devicePixelRatio||1,2);
  canvas.width=w*d;canvas.height=h*d;
  const c=canvas.getContext('2d');c.scale(d,d);c.fillStyle=colors[0];c.fillRect(0,0,w,h);
  let seed=173;function random(){seed=seed*16807%2147483647;return seed/2147483647}
  c.fillStyle=colors[1];c.globalAlpha=.15;
  for(let i=0;i<w*h/13;i++)c.fillRect(random()*w,random()*h,random()*1.8+.3,.6);
  c.globalAlpha=1;c.translate(w*.53,h*.54);let s=Math.min(w/290,h/128);c.scale(s,s);c.lineWidth=1.15;c.strokeStyle=colors[1];c.lineCap='round';
  function line(path){c.stroke(new Path2D(path))}
  function shape(path,fill){let p=new Path2D(path);c.fillStyle=fill;c.fill(p);c.stroke(p)}
  function leaf(x,y,length,width,angle){
    c.save();c.translate(x,y);c.rotate(angle);c.scale(length/60,width/15);
    shape('M0 0 Q22 -24 60 0 Q25 22 0 0Z',colors[2]);line('M0 0 Q28 -2 59 0');
    for(let i=8;i<=46;i+=6){let v=10*Math.sin(i*Math.PI/60);line('M'+i+' 0 q4 -1 9 -'+v+' M'+i+' 0 q4 1 9 '+v)}
    c.restore();
  }
  if(kind==='flower'){
    line('M-73 76 Q-38 26 17 -20 M-34 33 Q-42 15 -58 -5 M-17 17 Q23 19 49 6 M-50 51 Q-50 28 -64 19');
    leaf(-30,28,48,11,-2.4);leaf(-16,18,55,11,.12);leaf(-49,52,42,10,-2.05);
    function bloom(x,y,r){c.save();c.translate(x,y);
      for(let ring=0;ring<2;ring++)for(let i=0;i<24;i++){c.save();c.rotate(i*Math.PI/12+ring*.13);let l=r*(ring?.72:1)*(.9+random()*.18);shape('M0 0 Q-9 -'+l*.7+' -2 -'+l+' Q6 -'+(l+5)+' 6 -'+l*.78+' Q5 -'+l*.4+' 0 0Z',ring?'#e9ae65':'#e4a060');line('M1 -6 Q2 -'+l*.54+' 1 -'+l*.9);c.restore()}
      c.fillStyle='#845730';c.beginPath();c.arc(0,0,r*.22,0,7);c.fill();c.fillStyle='#e5b975';for(let i=0;i<55;i++){let a=random()*7,rr=Math.sqrt(random())*r*.21;c.fillRect(Math.cos(a)*rr,Math.sin(a)*rr,1,1)}c.restore()}
    bloom(20,-18,41);bloom(-59,-10,20);
  } else {
    line('M-100 58 Q-45 34 -19 12 Q17 -13 67 -48 M-49 33 Q-58 17 -60 0 M-17 10 Q-5 23 10 29 M15 -10 Q19 -30 17 -42 M42 -31 Q58 -23 76 -22');
    leaf(-50,30,49,20,-2.12);leaf(-21,13,54,22,.4);leaf(16,-12,42,18,-1.57);leaf(37,-27,47,18,.08);
    if(kind==='pea'||kind==='bean'){
      function pod(x,y,a,k){c.save();c.translate(x,y);c.rotate(a);c.scale(k,k);
        shape('M0 0 Q11 -9 28 -5 Q56 -3 78 7 Q87 11 93 9 Q81 19 67 20 Q31 19 7 6Z',colors[2]);line('M3 1 Q45 15 87 12');
        for(let i=0;i<6;i++){let px=13+i*10,py=2+i*1.5;c.beginPath();c.ellipse(px,py,5.1,4,0,Math.PI,2*Math.PI);c.stroke()}
        c.restore()}
      pod(-40,27,kind==='pea'?.31:.72,.93);pod(35,-28,.87,.88);
    }
    line('M63 -45 C79 -53 92 -52 91 -41 C90 -32 77 -34 81 -42 Q84 -47 86 -42 M-60 5 C-69 -10 -76 -12 -80 -7 Q-84 0 -78 0');
  }
}

(() => {
  const canvas = document.querySelector('#botanical');
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  ctx.scale(2, 2);

  function stroke(color, width, draw) {
    ctx.beginPath();
    draw(ctx);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke();
  }

  function leaf(x, y, angle, size, width, wash) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(size * .19, -width, size * .68, -width * 1.19, size, -width * .24);
    ctx.bezierCurveTo(size * .74, width * .58, size * .27, width * .9, 0, 0);
    ctx.fillStyle = wash;
    ctx.fill();
    ctx.strokeStyle = '#587953';
    ctx.lineWidth = .85;
    ctx.stroke();
    stroke('#567451', .65, p => {
      p.moveTo(0, 0);
      p.quadraticCurveTo(size * .46, -width * .13, size, -width * .24);
      for (let n = .22; n < .83; n += .105) {
        p.moveTo(size * n, -width * .13);
        p.quadraticCurveTo(size * (n + .06), -width * .35, size * (n + .15), -width * (.7 - Math.abs(n - .46)));
        p.moveTo(size * n, -width * .13);
        p.quadraticCurveTo(size * (n + .07), width * .23, size * (n + .15), width * (.41 - Math.abs(n - .46) * .55));
      }
    });
    ctx.restore();
  }

  function flower(x, y, r, angle) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    for (let n = 0; n < 13; n++) {
      ctx.rotate(Math.PI * 2 / 13);
      ctx.beginPath();
      ctx.moveTo(r * .22, 0);
      ctx.bezierCurveTo(r * .59, -r * .20, r, -r * .18, r, 0);
      ctx.bezierCurveTo(r, r * .18, r * .62, r * .21, r * .22, 0);
      ctx.fillStyle = n % 2 ? '#dcbd76' : '#e6cf92';
      ctx.fill();
      ctx.strokeStyle = '#a27c41';
      ctx.lineWidth = .65;
      ctx.stroke();
      stroke('#b48d4f', .55, p => {
        p.moveTo(r * .31, 0);
        p.quadraticCurveTo(r * .7, -.05 * r, r * .94, 0);
      });
    }
    ctx.beginPath();
    ctx.arc(0, 0, r * .29, 0, Math.PI * 2);
    ctx.fillStyle = '#a17b42';
    ctx.fill();
    for (let n = 0; n < 21; n++) {
      const a = n * 2.39996;
      const d = Math.sqrt(n / 21) * r * .24;
      ctx.fillStyle = n % 2 ? '#ead5a0' : '#775f38';
      ctx.fillRect(Math.cos(a) * d, Math.sin(a) * d, 1.3, 1.3);
    }
    ctx.restore();
  }

  function peaPod(x, y, angle) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(22, -23, 67, -22, 112, -2);
    ctx.bezierCurveTo(94, 3, 82, 16, 59, 19);
    ctx.bezierCurveTo(32, 23, 12, 14, 0, 0);
    const fill = ctx.createLinearGradient(0, -20, 0, 20);
    fill.addColorStop(0, '#b7c89c');
    fill.addColorStop(1, '#86a276');
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.strokeStyle = '#587851';
    ctx.lineWidth = 1.1;
    ctx.stroke();
    for (let n = 0; n < 5; n++) {
      const cx = 21 + n * 16;
      const cy = n < 3 ? 3 : 3 - (n - 2) * 2;
      ctx.beginPath();
      ctx.ellipse(cx, cy, 8 - n * .4, 9 - n * .7, -.2, -.6, 2.75);
      ctx.strokeStyle = '#64845a';
      ctx.lineWidth = .65;
      ctx.stroke();
      stroke('#698760', .45, p => {
        for (let k = 0; k < 5; k++) {
          p.moveTo(cx - 7 + k * 2.5, cy + 6);
          p.lineTo(cx - 3 + k * 2.8, cy + 11 - n * .62);
        }
      });
    }
    stroke('#57774f', .9, p => {
      p.moveTo(-13, -5);
      p.quadraticCurveTo(1, 0, 11, 3);
      p.bezierCurveTo(39, 15, 81, 10, 112, -2);
    });
    ctx.restore();
  }

  // The curves follow a loose botanical plate, with engraved veins and seed pods.
  stroke('#5b7852', 1.4, p => {
    p.moveTo(159, 225); p.bezierCurveTo(219, 136, 327, 113, 384, 43);
    p.moveTo(185, 205); p.bezierCurveTo(279, 185, 337, 184, 436, 140);
    p.moveTo(268, 145); p.bezierCurveTo(263, 114, 260, 72, 285, 39);
    p.moveTo(328, 102); p.bezierCurveTo(366, 111, 408, 86, 423, 61);
    p.moveTo(297, 126); p.bezierCurveTo(310, 111, 311, 96, 323, 77);
    p.moveTo(235, 169); p.bezierCurveTo(208, 166, 198, 144, 208, 131);
    p.bezierCurveTo(218, 118, 233, 133, 221, 140);
    p.bezierCurveTo(215, 144, 211, 138, 217, 135);
    p.moveTo(384, 43); p.bezierCurveTo(392, 22, 411, 26, 411, 34);
    p.bezierCurveTo(411, 43, 397, 44, 400, 35);
    p.moveTo(360, 168); p.bezierCurveTo(392, 175, 425, 184, 464, 166);
    p.moveTo(409, 150); p.bezierCurveTo(417, 120, 439, 102, 462, 91);
  });

  leaf(207, 180, -2.88, 90, 19, '#b8cbaa');
  leaf(229, 170, -1.68, 65, 17, '#a6bc97');
  leaf(264, 145, .43, 87, 22, '#a8c09c');
  leaf(276, 75, -2.41, 54, 13, '#c2d2b2');
  leaf(270, 105, -2.8, 77, 19, '#b4c9a7');
  leaf(313, 115, -.09, 62, 14, '#c3d1ad');
  leaf(355, 77, -1.85, 67, 15, '#b5caa6');
  leaf(373, 61, -.18, 83, 16, '#9fb996');
  leaf(351, 109, .35, 57, 12, '#bdcfac');
  leaf(407, 81, -.13, 59, 12, '#c1d0af');
  leaf(322, 180, -.96, 48, 11, '#bccfad');
  leaf(369, 165, -1.04, 44, 9, '#a8bf9b');
  leaf(401, 174, .72, 45, 10, '#b9cba9');
  leaf(441, 106, -.08, 50, 9, '#b2c6a5');
  peaPod(321, 80, -1.02);
  peaPod(242, 177, .23);

  flower(285, 38, 22, .2);
  flower(425, 58, 16, -.14);
  flower(465, 91, 19, .45);
  flower(464, 165, 13, -.2);

  let seed = 203;
  for (let n = 0; n < 2700; n++) {
    seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
    const x = seed / 4294967296 * 530;
    seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
    const y = seed / 4294967296 * 210;
    ctx.fillStyle = n % 2 ? '#3b533311' : '#ffffff3a';
    ctx.fillRect(x, y, .58, .58);
  }
})();

'use strict';

const $ = (selector, root = document) => root.querySelector(selector);
const all = (selector, root = document) => Array.from(root.querySelectorAll(selector));
const paths = {
  sprout: '<path d="M12 21v-8m0 2C5 15 3 11 3 6c5 0 9 3 9 8m0 0c0-5 4-9 9-9 0 6-3 9-9 9M8 21h8"/>',
  catalog: '<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M4 8h16m-8 3v7m-3-4h6"/>',
  history: '<path d="M3 12a9 9 0 1 1 2.64 6.36M3 12V6m0 6h6m3-5v5l3 2"/>',
  printer: '<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v7H6zm12-2h1"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  packet: '<path d="M5 3h14v18H5zM5 7h14m-7 11v-4m0 1c-3 0-4-2-4-4 3 0 4 2 4 4m0 0c0-3 2-4 4-4 0 2-1 4-4 4"/>',
  layers: '<path d="m12 3 9 5-9 5-9-5zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',
  alert: '<path d="m10.28 4.2-8.03 14A1.8 1.8 0 0 0 3.8 21h16.4a1.8 1.8 0 0 0 1.55-2.8l-8.03-14a2 2 0 0 0-3.44 0ZM12 9v4m0 4h.01"/>',
  search: '<circle cx="10.8" cy="10.8" r="6.4"/><path d="m16 16 4 4"/>',
  filter: '<path d="M4 6h16M7 12h10m-7 6h4"/>',
  arrow: '<path d="M5 12h14m-5-5 5 5-5 5"/>',
  chevron: '<path d="m10 6 6 6-6 6"/>',
  flower: '<path d="M12 9c-5-6 2-9 2-3v3c5-4 9 2 4 4l-3 1c6 3 2 9-2 4l-1-2c-1 6-8 4-5 0l2-2c-6 1-7-6-2-5l3 1c-3-4 0-6 2-1Z"/><circle cx="12" cy="12" r="2"/>',
  bean: '<path d="M13 3c5-1 9 2 8 7-1 6-6 11-12 11-5 0-8-5-5-9 2-3 6-1 7-4 1-2 0-4 2-5Z"/><path d="M7 15c4 1 7-1 8-5"/>',
  count: '<rect x="5" y="5" width="14" height="16" rx="2"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="M9 12h6m-6 4h6"/>',
  checkout: '<path d="M11 5H5v14h6m2-11 4 4-4 4m4-4H8"/>',
  undo: '<path d="M9 6 4 11l5 5m-5-5h10a5 5 0 0 1 5 5v2"/>',
  close: '<path d="m6 6 12 12M18 6 6 18"/>'
};

function icon(name) {
  return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${paths[name]}</svg>`;
}
for (const item of all('[data-icon]')) item.innerHTML = icon(item.dataset.icon);

const entities = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const escape = value => String(value).replace(/[&<>"']/g, character => entities[character]);
const normalize = value => value.normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase();
const numeric = new Intl.NumberFormat();
const format = value => numeric.format(value);
const deltaFormat = new Intl.NumberFormat(undefined, { signDisplay: 'exceptZero' });
const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
const dateOnly = new Intl.DateTimeFormat(undefined, { dateStyle: 'long' });
const pack = value => `${format(value)} ${value === 1 ? 'packet' : 'packets'}`;
const pages = { catalog: 'Catalog', activity: 'Activity', shelf: 'Shelf list' };
const types = {
  opening: ['Opening balance', 'layers'],
  checkout: ['Checkout', 'checkout'],
  donation: ['Donation', 'plus'],
  correction: ['Count correction', 'count'],
  undo: ['Undo', 'undo']
};

let data;
let counts;
let byEntry;
let undone;
let selectedId = 1;
let page = 'catalog';
let lowOnly = false;
let activityLot = '';
let editing;
let busy = false;
let toastTimer;

function refreshStorage() {
  const warning = $('#storage-error');
  try {
    data = Inventory.load();
    warning.hidden = true;
    $('#storage-caption').textContent = 'Saved on this device';
  } catch {
    data ??= Inventory.openingState();
    warning.textContent = 'Saved stock could not be loaded. Stock changes require access to this browser’s local storage.';
    warning.hidden = false;
    $('#storage-caption').textContent = 'Storage unavailable';
  }
}

const findLot = id => data.lots.find(lot => lot.id === id);
const isLow = count => count <= Inventory.lowLimit;

function badge(count) {
  const status = count === 0 ? 'Out of stock' : isLow(count) ? 'Low stock' : 'In stock';
  return `<span class="stock${isLow(count) ? ' low' : ''}"><i></i>${status}</span>`;
}

function lotIcon(variety) {
  const value = variety.toLowerCase();
  const name = value.includes('calendula') ? 'flower' : value.includes('bean') ? 'bean' : 'sprout';
  return `<span class="seed-icon ${name}" data-icon>${icon(name)}</span>`;
}

function render() {
  counts = Inventory.balances(data);
  byEntry = new Map(data.entries.map(entry => [entry.id, entry]));
  undone = new Set(data.entries.map(entry => entry.reverses).filter(Boolean));

  const quantities = Array.from(counts.values());
  const total = quantities.reduce((sum, value) => sum + BigInt(value), 0n);
  $('#packet-total').textContent = format(total);
  $('#lot-total').textContent = format(data.lots.length);
  $('#low-total').textContent = format(quantities.filter(isLow).length);

  if (page === 'catalog') renderCatalog();
  if (page === 'activity') renderActivity();
  if (page === 'shelf') renderShelf();
}

function renderCatalog() {
  const tokens = normalize($('#search').value).trim().split(/\s+/).filter(Boolean);
  const matches = data.lots.filter(lot => {
    const haystack = normalize(`${lot.variety} ${lot.code}`);
    return (!lowOnly || isLow(counts.get(lot.id))) && tokens.every(token => haystack.includes(token));
  });
  $('#inventory-rows').innerHTML = matches.map(lot => {
    const count = counts.get(lot.id);
    const active = lot.id === selectedId;
    const name = escape(`${lot.variety}, lot ${lot.code}`);
    return `<tr data-lot="${lot.id}" class="${active ? 'selected' : ''}">
      <td><span class="variety-cell">${lotIcon(lot.variety)}<strong>${escape(lot.variety)}</strong></span></td>
      <td class="lot-code">${escape(lot.code)}</td>
      <td class="number">${format(count)}</td><td>${badge(count)}</td>
      <td><button type="button" class="icon-button" data-select="${lot.id}" aria-label="View ${name}" aria-controls="lot-panel"${active ? ' aria-current="true"' : ''}>${icon('chevron')}</button></td>
    </tr>`;
  }).join('') || '<tr><td colspan="5" class="empty">No matching lots. Try another search or clear the low-stock filter.</td></tr>';
  $('#results-count').textContent = `Showing ${format(matches.length)} of ${format(data.lots.length)} lots`;
  renderLot();
}

function renderLot() {
  const lot = findLot(selectedId);
  if (!lot) return;
  const count = counts.get(lot.id);
  const events = data.entries.filter(entry => entry.lotId === lot.id).slice(-4).reverse();
  $('#lot-panel').innerHTML = `<div class="lot-head">
      <div class="lot-kicker">Selected lot ${badge(count)}</div>
      <h2 id="lot-heading" tabindex="-1">${escape(lot.variety)}</h2><span class="lot-code">${escape(lot.code)}</span>
      <div class="lot-balance"><strong>${format(count)}</strong> ${count === 1 ? 'packet available' : 'packets available'}</div>
      <div class="lot-actions">
        <button type="button" class="button primary" data-entry="checkout"${count === 0 ? ' disabled' : ''}>${icon('checkout')} Checkout</button>
        <button type="button" class="button secondary" data-entry="correction">${icon('count')} Correct count</button>
      </div>
    </div>
    <div class="lot-activity">
      <div class="activity-heading"><h3>Recent activity</h3><button type="button" class="text-button" id="view-lot-activity">View all <span aria-hidden="true">↗</span></button></div>
      ${eventList(events)}
    </div>`;
}

function eventList(entries, includeLot = false) {
  if (!entries.length) return '<p class="empty">No activity for this selection.</p>';
  return `<ol class="events">${entries.map(entry => {
    const [label, symbol] = types[entry.type];
    const lot = findLot(entry.lotId);
    const time = entry.at ? dateTime.format(new Date(entry.at)) : 'Initial inventory';
    const original = byEntry.get(entry.reverses);
    const lotLabel = `${lot.variety} · ${lot.code}`;
    let note = '';
    if (entry.type === 'correction') note = `Counted ${pack(entry.counted)}. ${entry.reason}`;
    if (original) note = `Reversed ${types[original.type][0].toLowerCase()} (${deltaFormat.format(original.delta)}) recorded ${dateTime.format(new Date(original.at))}.`;
    const reversed = undone.has(entry.id);
    const undoButton = !reversed && entry.type !== 'opening' && entry.type !== 'undo';
    return `<li class="event">
      <span data-icon class="event-icon${entry.type === 'undo' ? ' amber' : ''}">${icon(symbol)}</span>
      <div class="event-main">
        <strong>${label}${reversed ? '<span class="event-undone">Undone</span>' : ''}</strong>
        <div class="event-meta">${includeLot ? `${escape(lotLabel)} · ` : ''}${escape(time)}</div>
        ${note ? `<p class="event-note">${escape(note)}</p>` : ''}
      </div>
      <div class="event-value">${deltaFormat.format(entry.delta)}<small>${format(entry.balance)} after</small>
        ${undoButton ? `<button type="button" class="text-button" data-undo="${entry.id}" aria-label="Undo ${label.toLowerCase()} for ${escape(lotLabel)}">Undo</button>` : ''}
      </div>
    </li>`;
  }).join('')}</ol>`;
}

function sortedLots() {
  return [...data.lots].sort((a, b) => a.variety.localeCompare(b.variety) || a.code.localeCompare(b.code, undefined, { numeric: true }));
}

function renderActivity() {
  const select = $('#activity-lot');
  select.innerHTML = '<option value="">All lots</option>' + sortedLots().map(lot =>
    `<option value="${lot.id}">${escape(lot.variety)} · ${escape(lot.code)}</option>`
  ).join('');
  select.value = activityLot;
  const events = data.entries.filter(entry => !activityLot || entry.lotId === Number(activityLot)).reverse();
  $('#activity-list').innerHTML = eventList(events, true);
}

function shelfTable() {
  return `<table class="shelf-table">
    <thead><tr><th scope="col">Variety</th><th scope="col">Lot</th><th scope="col" class="number">Packets</th><th scope="col">Status</th><th scope="col">Counted</th></tr></thead>
    <tbody>${sortedLots().map(lot => {
      const count = counts.get(lot.id);
      const status = count === 0 ? 'Out of stock' : isLow(count) ? 'Low stock' : 'In stock';
      return `<tr><td>${escape(lot.variety)}</td><td>${escape(lot.code)}</td><td class="number">${format(count)}</td><td>${status}</td><td></td></tr>`;
    }).join('')}</tbody></table>`;
}

function renderShelf() {
  $('.shelf-panel').innerHTML = shelfTable();
}

function preparePrint() {
  const stamp = dateOnly.format(new Date());
  $('#print-sheet').innerHTML = `<h1>Seed Library Shelf List</h1><p>${escape(stamp)} · Low stock at 3 packets or fewer</p>${shelfTable()}`;
}

function navigate(next, filter = '') {
  activityLot = filter;
  page = next;
  for (const name of Object.keys(pages)) {
    const current = name === page;
    const control = $(`[data-page="${name}"]`);
    if (current) control.setAttribute('aria-current', 'page');
    else control.removeAttribute('aria-current');
    $(`#${name}-page`).hidden = !current;
  }
  $('#crumb').textContent = pages[page];
  render();
  $('#main').focus();
  window.scrollTo(0, 0);
}

const dialog = $('#entry-dialog');
const fields = $('#entry-fields');
const form = $('#entry-form');
const entryError = $('#entry-error');
const submit = $('#entry-submit');

const quantityField = (label, hint, value = '') => `<div class="field"><label for="field-quantity">${label}</label>
  <input id="field-quantity" name="quantity" type="text" inputmode="numeric" pattern="[0-9]+" required autocomplete="off" maxlength="16" value="${value}" aria-describedby="quantity-hint">
  <small id="quantity-hint">${hint}</small></div>`;

function openEntry(type, lotId, entryId) {
  const lot = findLot(lotId);
  const count = counts.get(lotId);
  editing = { type, lotId, entryId, trigger: document.activeElement };
  let title;
  let context;
  let submitText;
  let content = '';

  if (type === 'donation') {
    title = 'Record donation';
    context = 'Use the packet label to enter the variety and lot code.';
    submitText = 'Save donation';
    const varieties = new Set(sortedLots().map(item => item.variety));
    content = `<div class="field"><label for="field-variety">Variety</label><input id="field-variety" name="variety" maxlength="70" required list="varieties" autocomplete="off">
      <datalist id="varieties">${Array.from(varieties, name => `<option value="${escape(name)}"></option>`).join('')}</datalist></div>
      <div class="field"><label for="field-code">Lot code</label><input id="field-code" name="code" maxlength="35" required list="donation-lots" autocomplete="off"><datalist id="donation-lots"></datalist></div>
      ${quantityField('Packets donated', 'Use a whole number greater than zero.')}`;
  } else {
    context = `${lot.variety} · ${lot.code} · ${pack(count)} available`;
    if (type === 'checkout') {
      title = 'Record checkout';
      submitText = 'Save checkout';
      content = quantityField('Packets taken', `Enter 1 to ${format(count)} packets.`, '1');
    } else if (type === 'correction') {
      title = 'Correct stock count';
      submitText = 'Save correction';
      content = `${quantityField('Packets counted', 'Enter the total you counted on the shelf.')}
        <div class="field"><label for="field-reason">Reason</label><input id="field-reason" name="reason" required maxlength="120" autocomplete="off" placeholder="e.g. Two damaged packets removed"></div>`;
    } else {
      const original = byEntry.get(entryId);
      title = 'Undo entry';
      submitText = 'Undo entry';
      content = `<p>Reverse this ${types[original.type][0].toLowerCase()} (${deltaFormat.format(original.delta)}). The original and the reversal will both appear in the activity history.</p>`;
    }
  }
  $('#entry-title').textContent = title;
  $('#entry-context').textContent = context;
  submit.textContent = submitText;
  fields.innerHTML = content;
  entryError.hidden = true;
  dialog.showModal();
  const initial = $('input', fields) ?? $('[data-close]', form);
  initial.focus();
  if (type === 'checkout') initial.select();
}

function suggestLots(event) {
  if (event.target.name !== 'variety') return;
  const value = event.target.value.trim().toLowerCase();
  $('#donation-lots').innerHTML = sortedLots().filter(lot => lot.variety.toLowerCase() === value)
    .map(lot => `<option value="${escape(lot.code)}"></option>`).join('');
}

function toast(message) {
  const target = $('#toast');
  clearTimeout(toastTimer);
  target.hidden = false;
  target.textContent = message;
  toastTimer = setTimeout(() => { target.hidden = true; }, 5000);
}

form.addEventListener('input', event => {
  event.target.removeAttribute('aria-invalid');
  entryError.hidden = true;
  suggestLots(event);
});
form.addEventListener('submit', async event => {
  event.preventDefault();
  if (busy || !editing) return;
  busy = true;
  submit.disabled = true;
  entryError.hidden = true;
  const operation = editing;
  let saved;
  try {
    saved = await Inventory.save({ ...Object.fromEntries(new FormData(form)), ...operation });
  } catch (error) {
    entryError.textContent = error instanceof Inventory.EntryError
      ? error.message : 'This change could not be saved. Check that browser storage is available and try again.';
    entryError.hidden = false;
    const field = error.field ? $(`#field-${error.field}`) : null;
    if (field) {
      field.setAttribute('aria-invalid', 'true');
      field.focus();
    }
  } finally {
    busy = false;
    submit.disabled = false;
  }
  if (!saved) return;

  data = saved.data;
  selectedId = saved.entry.lotId;
  $('#storage-error').hidden = true;
  $('#storage-caption').textContent = 'Saved on this device';
  if (page === 'catalog' && operation.type === 'donation') {
    $('#search').value = '';
    lowOnly = false;
    $('#low-filter').setAttribute('aria-pressed', 'false');
  }
  dialog.close();
  render();
  const lot = findLot(selectedId);
  toast(`${types[saved.entry.type][0]} saved. ${lot.variety} (${lot.code}) has ${pack(saved.entry.balance)} available.`);
  if (operation.trigger?.isConnected) operation.trigger.focus();
  else if (page === 'catalog') $('#lot-heading').focus();
  else $('#main').focus();
});
dialog.addEventListener('cancel', event => { if (busy) event.preventDefault(); });
dialog.addEventListener('close', () => { editing = null; });

document.addEventListener('click', event => {
  const control = event.target.closest('button');
  const row = event.target.closest('[data-lot]');
  if (row) {
    selectedId = Number(row.dataset.lot);
    renderCatalog();
    if (window.matchMedia('(max-width: 1000px)').matches) {
      $('#lot-heading').focus();
    } else {
      $(`[data-select="${selectedId}"]`).focus({ preventScroll: true });
    }
  }
  if (!control) return;
  if (control.dataset.page) navigate(control.dataset.page);
  if (control.dataset.entry) openEntry(control.dataset.entry, selectedId);
  if (control.dataset.undo) {
    const entry = byEntry.get(Number(control.dataset.undo));
    openEntry('undo', entry.lotId, entry.id);
  }
  if (control.hasAttribute('data-close') && !busy) dialog.close();
  if (control.id === 'donate') openEntry('donation');
  if (control.id === 'view-lot-activity') navigate('activity', String(selectedId));
  if (control.id === 'low-filter') {
    lowOnly = !lowOnly;
    control.setAttribute('aria-pressed', String(lowOnly));
    renderCatalog();
  }
  if (control.id === 'print') {
    preparePrint();
    window.print();
  }
});

$('#search').addEventListener('input', renderCatalog);
$('#activity-lot').addEventListener('change', event => {
  activityLot = event.target.value;
  renderActivity();
});
document.addEventListener('keydown', event => {
  if (event.key === '/' && page === 'catalog' && !dialog.open && !event.altKey && !event.ctrlKey && !event.metaKey &&
      !event.target.closest('input, textarea, select, [contenteditable]')) {
    event.preventDefault();
    $('#search').focus();
  }
});
window.addEventListener('beforeprint', preparePrint);
window.addEventListener('storage', event => {
  if (event.key === Inventory.key || event.key === null) {
    refreshStorage();
    render();
  }
});

refreshStorage();
render();

'use strict';

const Inventory = (() => {
  const key = 'seed-library.inventory.v1';
  const lowLimit = 3;

  function openingState() {
    const rows = [['Snow Pea', 'P26-01', 17], ['Calendula', 'C26-02', 9], ['Bush Bean', 'B25-04', 4]];
    return {
      version: 1,
      lots: rows.map(([variety, code], index) => ({ id: index + 1, variety, code })),
      entries: rows.map(([, , count], index) => ({
        id: index + 1, lotId: index + 1, type: 'opening', delta: count, balance: count, at: null
      }))
    };
  }

  function load() {
    const raw = localStorage.getItem(key);
    if (raw === null) return openingState();
    const data = JSON.parse(raw);
    if (data?.version !== 1 || !Array.isArray(data.lots) || !Array.isArray(data.entries) || !data.lots.length) {
      throw new Error('The saved inventory could not be read.');
    }
    return data;
  }

  function balances(data) {
    const result = new Map();
    for (const item of data.entries) result.set(item.lotId, item.balance);
    return result;
  }

  function quantity(value, min) {
    if (!/^\d+$/.test(value) || !Number.isSafeInteger(Number(value)) || Number(value) < min) {
      throw new EntryError(min ? 'Enter a positive whole number of packets.' : 'Enter a whole number of packets, zero or more.', 'quantity');
    }
    return Number(value);
  }

  const clean = value => value.trim().replace(/\s+/g, ' ');
  const fold = value => clean(value).toLowerCase();

  class EntryError extends Error {
    constructor(message, field) {
      super(message);
      this.field = field;
    }
  }

  function apply(data, input, at = new Date().toISOString()) {
    let lot = data.lots.find(item => item.id === input.lotId);
    const counts = balances(data);
    let delta;
    let reason;
    let reverses;
    let counted;
    let added = false;

    if (input.type === 'donation') {
      const variety = clean(input.variety);
      const code = clean(input.code).toUpperCase();
      if (!variety || variety.length > 70) throw new EntryError('Enter a variety name up to 70 characters.', 'variety');
      if (!code || code.length > 35) throw new EntryError('Enter a lot code up to 35 characters.', 'code');
      delta = quantity(input.quantity, 1);
      lot = data.lots.find(item => fold(item.variety) === fold(variety) && fold(item.code) === fold(code));
      if (!lot) {
        const knownVariety = data.lots.find(item => fold(item.variety) === fold(variety));
        lot = { id: data.lots.at(-1).id + 1, variety: knownVariety?.variety ?? variety, code };
        added = true;
      }
    } else {
      if (!lot) throw new EntryError('Select a lot and try again.');
      const available = counts.get(lot.id);
      if (input.type === 'checkout') {
        delta = -quantity(input.quantity, 1);
        if (available + delta < 0) throw new EntryError(`Only ${available} packets are available in this lot.`, 'quantity');
      } else if (input.type === 'correction') {
        counted = quantity(input.quantity, 0);
        reason = clean(input.reason);
        if (!reason || reason.length > 120) throw new EntryError('Enter a short reason up to 120 characters.', 'reason');
        delta = counted - available;
      } else if (input.type === 'undo') {
        const original = data.entries.find(item => item.id === input.entryId && item.lotId === lot.id);
        if (!original || original.type === 'opening' || original.type === 'undo') throw new EntryError('This entry cannot be undone.');
        if (data.entries.some(item => item.reverses === original.id)) throw new EntryError('This entry has already been undone.');
        delta = -original.delta;
        reverses = original.id;
        if (available + delta < 0) throw new EntryError('Undoing this entry would make stock negative. Check later activity for this lot.');
      } else {
        throw new EntryError('Choose a stock action.');
      }
    }

    const balance = (counts.get(lot.id) ?? 0) + delta;
    if (!Number.isSafeInteger(balance)) throw new EntryError('The resulting lot count is too large.', 'quantity');
    const entry = {
      id: data.entries.at(-1).id + 1, lotId: lot.id, type: input.type, delta, balance, at,
      ...(reason && { reason, counted }), ...(reverses && { reverses })
    };
    if (added) data.lots.push(lot);
    data.entries.push(entry);
    return entry;
  }

  async function save(input) {
    // Read, apply and save together so a second open desk tab uses the latest counts.
    function commit() {
      const data = load();
      const entry = apply(data, input);
      localStorage.setItem(key, JSON.stringify(data));
      return { data, entry };
    }
    if (typeof navigator.locks?.request === 'function') {
      return navigator.locks.request(key, commit);
    }
    return commit();
  }

  return { key, load, save, balances, lowLimit, openingState, EntryError };
})();

:root {
  color-scheme: light;
  --bg: #f7f7f0;
  --paper: #fffefa;
  --ink: #202e26;
  --muted: #536359;
  --line: #dce3d8;
  --green: #235542;
  --deep: #18362d;
  --green-soft: #e9f0e5;
  --amber-ink: #77501b;
  --amber-soft: #f7edd8;
  --red: #8d352d;
  --serif: Georgia, "Times New Roman", serif;
  --sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin: 0; background: var(--bg); color: var(--ink); font: 15px/1.5 var(--sans); }
button, input, select { font: inherit; }
button { cursor: pointer; }
button:disabled { cursor: default; opacity: .5; }
button, input, select { touch-action: manipulation; }
button { transition: background-color 160ms, border-color 160ms, color 160ms; }
button:focus-visible, input:focus-visible, select:focus-visible, a:focus-visible { outline: 2px solid #658855; outline-offset: 3px; }
h1, h2, h3, p { margin: 0; }
h1, h2 { font-family: var(--serif); font-weight: 400; }
.icon { display: block; width: 19px; height: 19px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.65; stroke-linecap: round; stroke-linejoin: round; }
[data-icon] { display: inline-flex; align-items: center; justify-content: center; flex: none; }
.sr, .skip:not(:focus) { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.skip { position: fixed; top: 12px; left: 12px; z-index: 4; background: var(--paper); color: var(--ink); padding: 8px 12px; }

.sidebar { position: fixed; inset: 0 auto 0 0; width: 226px; background: var(--deep); color: #f6f6e9; display: flex; flex-direction: column; padding: 31px 17px 22px; }
.brand { display: flex; align-items: center; gap: 11px; margin: 0 6px 44px; }
.brand-icon { width: 43px; height: 43px; border-radius: 12px; color: #264b35; background: #dce9cb; }
.brand-icon .icon { width: 25px; height: 25px; }
.brand strong { display: block; font: 22px/1.14 var(--serif); white-space: nowrap; }
.brand div > span { display: block; color: #bdd0bc; font-size: 10px; letter-spacing: .13em; margin-top: 5px; font-weight: 650; }
.sidebar nav { display: grid; gap: 6px; }
.sidebar nav button { border: 1px solid transparent; background: transparent; color: #c9d8ce; display: flex; align-items: center; gap: 12px; text-align: left; border-radius: 8px; padding: 0 13px; min-height: 47px; font-size: 14px; font-weight: 550; }
.sidebar nav button:hover { background: #24483a; color: white; }
.sidebar nav [aria-current] { background: #315443; border-color: #466452; color: #fffef5; }
.sidebar nav [aria-current] .icon { color: #dce9cb; }
.offline { display: flex; gap: 10px; align-items: flex-start; margin: auto 8px 0; padding: 19px 1px 3px; border-top: 1px solid #3c594d; }
.offline-dot { background: #a9c992; width: 8px; height: 8px; border-radius: 50%; margin-top: 6px; flex: none; }
.offline strong, .offline div > span { display: block; }
.offline strong { font-size: 12px; font-weight: 650; }
.offline div > span { color: #b5cbba; font-size: 11px; margin-top: 3px; }
.workspace { margin-left: 226px; }
.topbar { min-height: 75px; padding: 12px 33px; border-bottom: 1px solid var(--line); background: var(--paper); display: flex; justify-content: space-between; gap: 16px; align-items: center; }
.breadcrumb, .top-actions { display: flex; align-items: center; gap: 11px; }
.breadcrumb { font-size: 13px; color: var(--muted); }
.breadcrumb .icon { width: 17px; height: 17px; color: var(--green); }
.breadcrumb strong { color: var(--ink); font-weight: 650; }
.slash { color: #728278; }
.button { min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 7px 13px; border: 1px solid transparent; border-radius: 8px; font-size: 13px; font-weight: 650; text-align: center; }
.button .icon { width: 17px; height: 17px; }
.primary { color: white; background: var(--green); border-color: var(--green); }
.primary:hover:not(:disabled) { background: #183d30; border-color: #183d30; }
.secondary { background: var(--paper); border-color: #cfd9ce; color: var(--green); }
.secondary:hover:not(:disabled), .secondary[aria-pressed="true"] { background: var(--green-soft); border-color: #a2b59e; }
main { outline: none; max-width: 1600px; margin-inline: auto; padding: 30px 33px 38px; }
.hero { position: relative; display: flex; align-items: center; min-height: 202px; overflow: hidden; isolation: isolate; border-radius: 15px; border: 1px solid #cbd9c4; background: radial-gradient(ellipse at 81% 22%, #eaf0df, transparent 55%), linear-gradient(104deg, #e3ecdb, #dbe7d4); }
.hero-copy { z-index: 1; position: relative; padding: 24px 32px; }
.eyebrow { color: #3e6149; font-size: 11px; font-weight: 750; letter-spacing: .145em; display: flex; align-items: center; gap: 8px; margin-bottom: 9px; }
.eyebrow span { display: inline-block; width: 16px; height: 1px; background: #65865f; }
h1 { font-size: clamp(41px, 4.2vw, 64px); line-height: 1.05; letter-spacing: -.051em; color: #203c2e; }
.hero p, .page-heading p { color: #405b49; margin-top: 13px; }
#botanical { position: absolute; right: 0; top: 50%; width: 530px; height: 210px; transform: translateY(-50%); object-fit: contain; pointer-events: none; }

.summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 15px; margin: 18px 0 25px; }
.stat { min-height: 88px; display: flex; align-items: center; gap: 13px; padding: 11px 16px; background: var(--paper); border: 1px solid var(--line); border-radius: 11px; }
.stat-icon, .seed-icon, .event-icon { border-radius: 9px; color: var(--green); background: var(--green-soft); }
.stat-icon { width: 45px; height: 45px; }
.stat-icon .icon { width: 21px; height: 21px; }
.amber { color: var(--amber-ink); background: var(--amber-soft); }
.stat strong, .stat div > span { display: block; }
.stat strong { font-size: 25px; letter-spacing: -.045em; font-weight: 690; line-height: 1.12; font-variant-numeric: tabular-nums; }
.stat div > span { color: var(--muted); font-size: 13px; margin-top: 4px; }
.desk-grid { display: grid; grid-template-columns: minmax(0, 1.95fr) minmax(295px, 1fr); gap: 18px; align-items: start; }
.panel { border: 1px solid var(--line); border-radius: 12px; background: var(--paper); min-width: 0; }
.catalog-header { padding: 18px 19px 15px; }
.panel-title h2, .lot-panel h2, .dialog-heading h2 { font-size: 29px; line-height: 1.16; letter-spacing: -.034em; }
.panel-title p { margin-top: 4px; color: var(--muted); font-size: 13px; }
.catalog-tools { display: flex; align-items: center; gap: 8px; margin-top: 14px; }
.search { border: 1px solid #cfd9ce; border-radius: 8px; min-height: 44px; flex: 1; min-width: 0; display: flex; align-items: center; gap: 9px; padding: 0 10px; color: var(--muted); }
.search:focus-within { outline: 2px solid #658855; outline-offset: 2px; }
.search input { width: 100%; min-width: 0; border: 0; outline: none; color: var(--ink); background: transparent; }
.search input:focus-visible { outline: none; }
.search .icon { width: 17px; height: 17px; }
.search input::placeholder { color: #58695d; font-size: 13px; }
kbd { border: 1px solid var(--line); border-radius: 4px; padding: 0 6px; background: #f4f6ef; font: 12px/20px var(--sans); }
.filter { flex: none; }
table { width: 100%; border-collapse: collapse; text-align: left; }
th { font-weight: 650; }
.inventory-table thead { background: #f1f4eb; color: #46594c; }
.inventory-table th { font-size: 11px; text-transform: uppercase; letter-spacing: .065em; padding: 9px 8px; white-space: nowrap; border-block: 1px solid var(--line); }
.inventory-table td { padding: 7px 8px; height: 63px; border-bottom: 1px solid var(--line); overflow-wrap: anywhere; }
.inventory-table td:first-child, .inventory-table th:first-child { padding-left: 19px; }
.inventory-table td:last-child, .inventory-table th:last-child { padding-right: 12px; }
.inventory-table td:last-child { width: 46px; }
.inventory-table tr[data-lot] { cursor: pointer; }
.inventory-table tr[data-lot]:hover td { background: #f3f7ef; }
.inventory-table tr.selected td { background: #edf3e9; }
.inventory-table tr.selected td:first-child { box-shadow: inset 3px 0 #72956b; }
.variety-cell { display: flex; align-items: center; gap: 10px; min-width: 0; }
.seed-icon { width: 34px; height: 34px; }
.seed-icon.flower { color: #82551d; background: #f5ebd6; }
.seed-icon.bean { color: #485b38; background: #e9ebdc; }
.seed-icon .icon { width: 18px; height: 18px; }
.variety-cell strong { font-size: 14px; font-weight: 650; }
.lot-code { font-family: ui-monospace, "Courier New", monospace; font-size: 12px; color: #435b49; overflow-wrap: anywhere; }
.number { text-align: right; font-variant-numeric: tabular-nums; font-weight: 670; }
.stock { display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px; color: #335a42; background: #e6efe2; font-size: 11px; font-weight: 680; white-space: nowrap; border-radius: 20px; }
.stock.low { color: var(--amber-ink); background: var(--amber-soft); }
.stock i, .stock-key i { width: 6px; height: 6px; border-radius: 50%; background: #658d65; flex: none; }
.stock.low i, .stock-key i { background: #ae772b; }
.icon-button, .text-button { min-height: 44px; border: 0; color: var(--green); background: transparent; border-radius: 7px; }
.icon-button { display: grid; place-items: center; width: 44px; padding: 0; }
.icon-button:hover, .text-button:hover { background: var(--green-soft); }
.catalog-foot { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 4px 10px; padding: 12px 19px; font-size: 11px; color: var(--muted); }
.stock-key { display: inline-flex; align-items: center; gap: 6px; }

.lot-panel { overflow-wrap: anywhere; }
.lot-head { padding: 18px 18px 14px; }
.lot-kicker { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 10px; letter-spacing: .115em; color: #506655; font-weight: 750; text-transform: uppercase; margin-bottom: 9px; }
.lot-kicker .stock { text-transform: none; letter-spacing: normal; }
.lot-head .lot-code { display: inline-block; margin-top: 4px; }
.lot-balance { border: 1px solid var(--line); background: #f2f5ec; border-radius: 9px; display: flex; align-items: center; gap: 11px; padding: 7px 12px; margin-top: 13px; font-size: 13px; color: var(--muted); }
.lot-balance strong { font: 400 33px/1.12 var(--serif); color: var(--deep); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.lot-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: 10px; }
.lot-actions .button { padding-inline: 6px; }
.lot-activity { border-top: 1px solid var(--line); padding: 6px 18px 11px; }
.activity-heading { display: flex; justify-content: space-between; align-items: center; gap: 5px; }
.activity-heading h3 { font-size: 13px; font-weight: 720; }
.text-button { padding: 4px 6px; font-size: 12px; font-weight: 680; }
.events { padding: 0; margin: 0; list-style: none; }
.event { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: start; gap: 9px; padding: 9px 0; }
.event + .event { border-top: 1px solid var(--line); }
.event-icon { width: 31px; height: 31px; margin-top: 2px; }
.event-icon .icon { width: 15px; height: 15px; }
.event-main strong { display: block; font-size: 13px; }
.event-meta, .event-note { color: var(--muted); font-size: 11px; overflow-wrap: anywhere; }
.event-note { margin-top: 3px; }
.event-value { font-size: 13px; text-align: right; font-weight: 700; font-variant-numeric: tabular-nums; }
.event-value small { display: block; color: var(--muted); font-weight: 500; font-size: 11px; }
.event-value .text-button { margin-top: 2px; }
.event-undone { font-size: 10px; padding: 1px 5px; margin-left: 4px; background: var(--amber-soft); color: var(--amber-ink); border-radius: 4px; white-space: nowrap; }
.empty { color: var(--muted); padding: 20px !important; overflow-wrap: anywhere; font-size: 14px; }
.page-heading { margin: 13px 0 23px; }
.log-toolbar { display: flex; align-items: center; gap: 12px; padding: 15px 20px; border-bottom: 1px solid var(--line); }
.log-toolbar label { font-size: 13px; font-weight: 680; flex: none; }
.log-toolbar select { max-width: min(70%, 420px); }
#activity-list .events { padding: 0 20px; }
#activity-list .event { padding: 12px 0; }
#activity-list .event-main strong, #activity-list .event-value { font-size: 15px; }
#activity-list .event-meta, #activity-list .event-note { font-size: 13px; }

.shelf-panel { overflow: hidden; }
.shelf-table th, .shelf-table td { padding: 11px 14px; border-bottom: 1px solid var(--line); overflow-wrap: anywhere; }
.shelf-table th { background: #eef2e8; color: #3a4f41; font-size: 13px; }
.shelf-table tbody tr:last-child td { border-bottom: 0; }
#print-sheet { display: none; }
.notice, .form-error { background: #f8e9e3; color: var(--red); padding: 9px 12px; border-radius: 7px; margin-bottom: 13px; overflow-wrap: anywhere; }
.toast { position: fixed; right: 22px; bottom: 20px; background: var(--deep); color: white; padding: 11px 16px; border-radius: 9px; box-shadow: 0 4px 15px #142c2334; max-width: min(410px, calc(100vw - 44px)); z-index: 2; }

dialog { width: min(460px, calc(100% - 28px)); max-height: calc(100% - 28px); border: 1px solid var(--line); border-radius: 15px; padding: 21px; background: var(--paper); color: var(--ink); box-shadow: 0 18px 60px #172f293c; }
dialog::backdrop { background: #10291e90; }
.dialog-heading { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; margin-bottom: 15px; }
.dialog-heading p { color: var(--muted); font-size: 13px; margin-top: 5px; overflow-wrap: anywhere; }
.dialog-heading .icon-button { margin: -7px -7px 0 0; }
.field { display: grid; gap: 5px; margin-bottom: 11px; }
.field label { font-size: 13px; font-weight: 680; }
.field input, select { border: 1px solid #c0cdbf; border-radius: 7px; min-height: 44px; padding: 7px 9px; background: white; color: var(--ink); min-width: 0; }
.field small { color: var(--muted); font-size: 12px; }
.dialog-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; margin-top: 16px; }

@media (max-width: 1170px) {
  .sidebar { width: 194px; padding-inline: 12px; }
  .workspace { margin-left: 194px; }
  .topbar, main { padding-inline: 23px; }
  .desk-grid { grid-template-columns: minmax(0, 1.7fr) minmax(275px, 1fr); gap: 12px; }
  .inventory-table td, .inventory-table th { padding-inline: 6px; }
  .inventory-table td:first-child, .inventory-table th:first-child { padding-left: 11px; }
  .inventory-table td:last-child, .inventory-table th:last-child { padding-right: 2px; }
  .variety-cell { gap: 7px; }
  #botanical { right: -30px; }
}
@media (max-width: 1000px) {
  .sidebar { width: 166px; }
  .brand { gap: 8px; margin-left: 2px; }
  .brand strong { font-size: 19px; }
  .brand-icon { width: 36px; height: 36px; }
  .brand div > span { font-size: 8px; }
  .workspace { margin-left: 166px; }
  .desk-grid { grid-template-columns: 1fr; }
  .lot-actions { max-width: 395px; }
  #botanical { right: -115px; opacity: .75; }
  .hero-copy { background: linear-gradient(90deg, #e3ecdb 72%, transparent); }
}
@media (max-width: 680px) {
  .sidebar { position: static; width: auto; padding: 12px 14px 7px; }
  .brand { margin: 0 0 8px; }
  .sidebar nav { display: flex; flex-wrap: wrap; gap: 4px; }
  .sidebar nav button { flex: 1 1 auto; justify-content: center; padding: 0 6px; gap: 6px; min-height: 44px; }
  .offline { position: absolute; top: 12px; right: 14px; margin: 0; padding: 0; border: 0; }
  .workspace { margin-left: 0; }
  .topbar, main { padding-inline: 13px; }
  .topbar { min-height: 63px; }
  .breadcrumb { display: none; }
  .top-actions { width: 100%; flex-wrap: wrap; gap: 6px; }
  .top-actions .button { flex: 1 1 auto; }
  main { padding-block: 15px 26px; }
  .hero { min-height: 151px; }
  .hero-copy { padding: 16px; background: linear-gradient(90deg, #e3ecdb 68%, transparent); }
  .hero p { font-size: 13px; max-width: 260px; }
  #botanical { width: 380px; height: auto; right: -139px; opacity: .46; }
  .summary { gap: 6px; margin: 10px 0 14px; }
  .stat { align-items: flex-start; flex-direction: column; gap: 6px; padding: 7px; min-height: 0; }
  .stat-icon { width: 29px; height: 29px; }
  .stat-icon .icon { width: 16px; height: 16px; }
  .stat strong { font-size: 21px; overflow-wrap: anywhere; }
  .stat div > span { font-size: 11px; margin-top: 1px; }
  .catalog-header { padding: 12px; }
  .catalog-foot { padding-inline: 11px; }
  .variety-cell .seed-icon { display: none; }
  .inventory-table .icon-button { width: 35px; }
  .inventory-table td:last-child { width: 37px; }
  .search kbd { display: none; }
  .shelf-table th, .shelf-table td { padding: 8px 6px; }
}
@media (prefers-reduced-motion: reduce) { button { transition: none; } }
@page { margin: 15mm; }
@media print {
  body { background: white; color: black; }
  body > :not(#print-sheet) { display: none !important; }
  #print-sheet { display: block; font-size: 11pt; }
  #print-sheet h1 { color: black; font-size: 27pt; letter-spacing: normal; }
  #print-sheet p { margin: 4pt 0 12pt; }
  .shelf-table th, .shelf-table td { border: 1px solid #555 !important; color: black; background: white; padding: 7pt; }
  .shelf-table tr { break-inside: avoid; }
}
